+#!/usr/bin/env node
+
+import fs from "fs";
+import path from "path";
+import { createAggregateIndex, queryOrgwide, RepoMetadata } from "../core/index-aggregate";
+
+const main = async () => {
+  // Load org configuration
+  const configPath = process.env.COMMITLORE_ORG_CONFIG || path.join(process.env.HOME || "", ".commitlore/org.json");
+
+  if (!fs.existsSync(configPath)) {
+    console.error(`Organization config not found at ${configPath}`);
+    console.error(`Create it with: { "repos": [{ "name": "repo1", "url": "https://..." }, ...] }`);
+    process.exit(1);
+  }
+
+  const config = JSON.parse(fs.readFileSync(configPath, "utf8"));
+  const repos: RepoMetadata[] = config.repos;
+
+  if (!repos || repos.length === 0) {
+    console.error("No repositories configured");
+    process.exit(1);
+  }
+
+  const searchTerm = process.argv[2] || "";
+  if (!searchTerm) {
+    console.error("Usage: org-query <search-term>");
+    console.error("Example: org-query authentication");
+    process.exit(1);
+  }
+
+  console.log(`Searching for "${searchTerm}" across ${repos.length} repositories...`);
+  console.log("Fetching indices...");
+
+  const db = createAggregateIndex({ repos });
+
+  const results = queryOrgwide(db, searchTerm);
+
+  if (results.length === 0) {
+    console.log("No results found.");
+    process.exit(0);
+  }
+
+  console.log(`\nFound ${results.length} matches:\n`);
+
+  // Group by repo
+  const byRepo: { [key: string]: typeof results } = {};
+  for (const result of results) {
+    if (!byRepo[result.repo]) byRepo[result.repo] = [];
+    byRepo[result.repo].push(result);
+  }
+
+  for (const [repoName, records] of Object.entries(byRepo)) {
+    console.log(`\n📦 ${repoName} (${records.length} records)`);
+    for (const record of records) {
+      console.log(`  • ${record.recordId}`);
+      console.log(`    Trailer: ${record.trailer.substring(0, 60)}...`);
+      console.log(`    Path: ${record.path}#${record.sha.substring(0, 8)}`);
+    }
+  }
+
+  db.close();
+};
+
+main().catch((err) => {
+  console.error(err);
+  process.exit(1);
+});
