+import Database from "better-sqlite3";
+import { execSync } from "child_process";
+import fs from "fs";
+import path from "path";
+import os from "os";
+
+export interface RepoMetadata {
+  name: string;
+  url: string;
+  refName?: string;
+}
+
+export interface AggregateOptions {
+  repos: RepoMetadata[];
+  tempDir?: string;
+}
+
+export interface Record {
+  repo: string;
+  recordId: string;
+  sha: string;
+  path: string;
+  trailer: string;
+}
+
+export const fetchIndexRef = (repoUrl: string, refName: string = "refs/commitlore/index"): Buffer => {
+  // Use ls-remote to get the commit hash for the ref
+  const lsRemoteOutput = execSync(`git ls-remote "${repoUrl}" "${refName}"`, {
+    encoding: "utf8",
+  }).trim();
+
+  if (!lsRemoteOutput) {
+    throw new Error(`Ref ${refName} not found in ${repoUrl}`);
+  }
+
+  const commitHash = lsRemoteOutput.split(/\s+/)[0];
+
+  // Create a temporary directory for fetching
+  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "commitlore-"));
+
+  try {
+    // Initialize a bare repo to fetch into
+    execSync(`git init --bare "${tmpDir}"`, { stdio: "pipe" });
+
+    // Fetch just the ref we need (shallow fetch)
+    execSync(`git fetch --depth=1 "${repoUrl}" "${refName}"`, {
+      cwd: tmpDir,
+      stdio: "pipe",
+    });
+
+    // Extract the index.db blob
+    const showOutput = execSync(`git show ${commitHash}:index.db`, {
+      cwd: tmpDir,
+      encoding: "binary",
+    });
+
+    return Buffer.from(showOutput, "binary");
+  } finally {
+    // Cleanup
+    execSync(`rm -rf "${tmpDir}"`, { stdio: "pipe" });
+  }
+};
+
+export const createAggregateIndex = (opts: AggregateOptions): Database.Database => {
+  const tempDir = opts.tempDir || fs.mkdtempSync(path.join(os.tmpdir(), "commitlore-agg-"));
+  const aggregateDbPath = path.join(tempDir, "aggregate.db");
+
+  const db = new Database(aggregateDbPath);
+
+  // Create the aggregate records table
+  db.exec(`
+    CREATE TABLE records (
+      repo TEXT NOT NULL,
+      record_id TEXT NOT NULL,
+      sha TEXT NOT NULL,
+      path TEXT NOT NULL,
+      trailer TEXT NOT NULL,
+      PRIMARY KEY (repo, record_id)
+    );
+
+    CREATE INDEX idx_record_id ON records(record_id);
+    CREATE INDEX idx_trailer ON records(trailer);
+  `);
+
+  // Fetch and load each repo's index
+  for (const repo of opts.repos) {
+    try {
+      const indexBuffer = fetchIndexRef(repo.url, repo.refName);
+      const indexPath = path.join(tempDir, `${repo.name}.db`);
+      fs.writeFileSync(indexPath, indexBuffer);
+
+      // Open the repo's index and copy records into aggregate
+      const repoDb = new Database(indexPath, { readonly: true });
+      const rows = repoDb.prepare("SELECT * FROM records").all() as any[];
+
+      const insert = db.prepare(
+        "INSERT INTO records (repo, record_id, sha, path, trailer) VALUES (?, ?, ?, ?, ?)"
+      );
+
+      for (const row of rows) {
+        insert.run(repo.name, row.record_id, row.sha, row.path, row.trailer);
+      }
+
+      repoDb.close();
+      fs.unlinkSync(indexPath);
+    } catch (error) {
+      console.warn(`Failed to fetch index for ${repo.name}: ${error instanceof Error ? error.message : error}`);
+    }
+  }
+
+  return db;
+};
+
+export const queryOrgwide = (
+  db: Database.Database,
+  searchTerm: string
+): Record[] => {
+  // Search across all record fields
+  const query = db.prepare(`
+    SELECT repo, record_id, sha, path, trailer FROM records
+    WHERE trailer LIKE ? OR record_id LIKE ? OR path LIKE ?
+    ORDER BY repo, record_id
+  `);
+
+  const pattern = `%${searchTerm}%`;
+  return query.all(pattern, pattern, pattern) as Record[];
+};
