+import Database from "better-sqlite3";
+import { execSync } from "child_process";
+
+export interface PublishOptions {
+  gitDir: string;
+  refName?: string;
+}
+
+export const publishIndex = (db: Database.Database, opts: PublishOptions): string => {
+  const refName = opts.refName || "refs/commitlore/index";
+  const dbPath = `${opts.gitDir}/commitlore/index.db`;
+
+  if (!require("fs").existsSync(dbPath)) {
+    throw new Error(`Index database not found at ${dbPath}. Build it first.`);
+  }
+
+  // Read the SQLite database as a binary blob
+  const fs = require("fs");
+  const dbBuffer = fs.readFileSync(dbPath);
+
+  // Create a Git blob from the database file
+  const hashObject = execSync(`git hash-object -w --stdin`, {
+    cwd: opts.gitDir,
+    input: dbBuffer,
+  })
+    .toString()
+    .trim();
+
+  // Create a commit that points to this blob
+  const treeHash = execSync(
+    `git mktree <<EOF
+100644 blob ${hashObject}	index.db
+EOF`,
+    { cwd: opts.gitDir, shell: true }
+  )
+    .toString()
+    .trim();
+
+  // Get commit metadata for the commit message
+  const headSha = execSync("git rev-parse HEAD", { cwd: opts.gitDir })
+    .toString()
+    .trim();
+  const headMessage = execSync("git log -1 --format=%s", { cwd: opts.gitDir })
+    .toString()
+    .trim();
+
+  // Create an annotated tag as the ref
+  const timestamp = new Date().toISOString();
+  const commitHash = execSync(
+    `git commit-tree ${treeHash} -m "CommitLore index snapshot at ${headSha}" -m "Built: ${timestamp}"`,
+    { cwd: opts.gitDir }
+  )
+    .toString()
+    .trim();
+
+  // Update the ref
+  execSync(`git update-ref ${refName} ${commitHash}`, { cwd: opts.gitDir });
+
+  return refName;
+};
