+import React, { useState } from "react";
+
+interface RepoMetadata {
+  name: string;
+  url: string;
+  gitApiUrl?: string; // e.g., https://api.github.com/repos/org/repo
+  refName?: string;
+}
+
+interface Record {
+  repo: string;
+  recordId: string;
+  sha: string;
+  path: string;
+  trailer: string;
+}
+
+interface QueryResult {
+  results: Record[];
+  repos: string[];
+  query: string;
+  duration: number;
+}
+
+export const OrgQuery: React.FC<{
+  repos: RepoMetadata[];
+}> = ({ repos }) => {
+  const [query, setQuery] = useState("");
+  const [results, setResults] = useState<QueryResult | null>(null);
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState("");
+
+  const fetchIndexBlob = async (repo: RepoMetadata): Promise<ArrayBuffer | null> => {
+    // Use GitHub/GitLab API to fetch the blob without full clone
+    // This is an example using GitHub API
+    if (!repo.gitApiUrl) {
+      console.warn(`No gitApiUrl for ${repo.name}, skipping`);
+      return null;
+    }
+
+    try {
+      const refName = repo.refName || "commitlore/index";
+      const apiUrl = `${repo.gitApiUrl}/git/refs/${refName}`;
+
+      // Get the commit hash for the ref
+      const refResponse = await fetch(apiUrl);
+      if (!refResponse.ok) {
+        console.warn(`Ref not found for ${repo.name}`);
+        return null;
+      }
+
+      const refData = await refResponse.json();
+      const commitHash = refData.object.sha;
+
+      // Get the tree from the commit
+      const commitUrl = `${repo.gitApiUrl}/git/commits/${commitHash}`;
+      const commitResponse = await fetch(commitUrl);
+      const commitData = await commitResponse.json();
+      const treeHash = commitData.tree.sha;
+
+      // Get the tree contents
+      const treeUrl = `${repo.gitApiUrl}/git/trees/${treeHash}`;
+      const treeResponse = await fetch(treeUrl);
+      const treeData = await treeResponse.json();
+
+      // Find index.db in the tree
+      const indexBlob = treeData.tree.find((item: any) => item.path === "index.db");
+      if (!indexBlob) {
+        console.warn(`index.db not found in ${repo.name}`);
+        return null;
+      }
+
+      // Get the blob
+      const blobUrl = `${repo.gitApiUrl}/git/blobs/${indexBlob.sha}`;
+      const blobResponse = await fetch(blobUrl);
+      if (!blobResponse.ok) return null;
+
+      return blobResponse.arrayBuffer();
+    } catch (err) {
+      console.error(`Error fetching index for ${repo.name}:`, err);
+      return null;
+    }
+  };
+
+  const handleSearch = async (e: React.FormEvent) => {
+    e.preventDefault();
+    if (!query.trim()) {
+      setError("Enter a search term");
+      return;
+    }
+
+    setLoading(true);
+    setError("");
+    setResults(null);
+
+    const startTime = performance.now();
+
+    try {
+      // This would require a SQLite WASM library for browser-side querying
+      // For now, this is a placeholder showing the structure
+      const allRecords: Record[] = [];
+      const reposQueried: string[] = [];
+
+      for (const repo of repos) {
+        const blob = await fetchIndexBlob(repo);
+        if (blob) {
+          reposQueried.push(repo.name);
+          // In a real implementation, use sql.js or similar to query the blob
+          // For now, just indicate it was fetched
+        }
+      }
+
+      const duration = performance.now() - startTime;
+      setResults({
+        results: allRecords,
+        repos: reposQueried,
+        query: query.trim(),
+        duration,
+      });
+    } catch (err) {
+      setError(err instanceof Error ? err.message : "Query failed");
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  return (
+    <div className="org-query">
+      <h1>CommitLore Org-Wide Search</h1>
+      <form onSubmit={handleSearch}>
+        <input
+          type="text"
+          value={query}
+          onChange={(e) => setQuery(e.target.value)}
+          placeholder="Search decisions (e.g., 'authentication')"
+          disabled={loading}
+        />
+        <button type="submit" disabled={loading}>
+          {loading ? "Searching..." : "Search"}
+        </button>
+      </form>
+
+      {error && <div className="error">{error}</div>}
+
+      {results && (
+        <div className="results">
+          <div className="summary">
+            Found {results.results.length} matches across {results.repos.length} repositories in{" "}
+            {(results.duration / 1000).toFixed(2)}s
+          </div>
+
+          {results.results.length === 0 ? (
+            <p>No results found for "{results.query}"</p>
+          ) : (
+            <div className="records">
+              {Object.entries(
+                results.results.reduce(
+                  (acc, r) => {
+                    if (!acc[r.repo]) acc[r.repo] = [];
+                    acc[r.repo].push(r);
+                    return acc;
+                  },
+                  {} as Record<string, Record[]>
+                )
+              ).map(([repo, records]) => (
+                <div key={repo} className="repo-group">
+                  <h3>📦 {repo}</h3>
